import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC03%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E7%B3%BB%E7%BB%9F%E6%B2%BB%E7%90%86/","title":"第03章 信息系统治理","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第03章 信息系统治理/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第03章-信息系统治理" tabindex="-1"><a class="header-anchor" href="#第03章-信息系统治理"><span>第03章 信息系统治理</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍信息系统治理的概念、IT治理框架以及数据治理的相关知识。</p><p><strong>重点知识点：</strong></p><ul><li>治理与管理的区别</li><li>IT治理框架</li><li>COBIT框架</li><li>数据治理</li></ul><hr><h2 id="_3-1-治理概念" tabindex="-1"><a class="header-anchor" href="#_3-1-治理概念"><span>3.1 治理概念</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>治理是指为实现组织目标而进行的决策和监督活动。</p><h3 id="治理与管理的区别" tabindex="-1"><a class="header-anchor" href="#治理与管理的区别"><span>治理与管理的区别</span></a></h3><table><thead><tr><th>维度</th><th>治理</th><th>管理</th></tr></thead><tbody><tr><td><strong>关注点</strong></td><td>做正确的事</td><td>正确地做事</td></tr><tr><td><strong>层级</strong></td><td>战略层</td><td>执行层</td></tr><tr><td><strong>责任</strong></td><td>董事会</td><td>管理层</td></tr></tbody></table><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>治理与管理的区别</li><li>治理的核心要素</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>治理定方向，管理抓执行</p><hr><h2 id="_3-2-it治理" tabindex="-1"><a class="header-anchor" href="#_3-2-it治理"><span>3.2 IT治理</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>IT治理是对IT资源和活动进行的治理，确保IT支持组织目标的实现。</p><h3 id="it治理框架" tabindex="-1"><a class="header-anchor" href="#it治理框架"><span>IT治理框架</span></a></h3><ul><li><strong>COBIT</strong>：IT治理的国际标准框架</li><li><strong>ITIL</strong>：IT服务管理最佳实践</li><li><strong>ISO/IEC 38500</strong>：IT治理标准</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>COBIT框架的核心组件</li><li>IT治理的目标</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>COBIT定框架，ITIL管服务</p><hr><h2 id="_3-3-数据治理" tabindex="-1"><a class="header-anchor" href="#_3-3-数据治理"><span>3.3 数据治理</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>数据治理是对数据资产进行全面管理的活动。</p><h3 id="核心要素" tabindex="-1"><a class="header-anchor" href="#核心要素"><span>核心要素</span></a></h3><ul><li>数据质量</li><li>数据安全</li><li>数据生命周期</li><li>数据标准</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>数据治理的核心要素</li><li>数据质量管理</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>数据治理保质量，全生命周期要管好</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};